window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cb53132001ee1c4c"]={"versions": [{"id": "FIG-cb53132001ee1c4c", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Initialisierung des Basissoftware-Moduls Diagnostic Log and Trace (DLT) innerhalb der AUTOSAR Classic Platform-Architektur. Dargestellt ist die synchrone Interaktion zwischen dem ECU State Manager (<code>EcuM</code>) als Aufrufer und dem DLT-Modul (<code>Dlt</code>) während der BSW-Startphase.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>EcuM</strong> (<code>«module» EcuM</code>): ECU State Manager als BSW-Komponente, agiert als Initiator des Initialisierungsaufrufs.\n</li><li><strong>Dlt</strong> (<code>«module» Dlt :Dlt</code>): Diagnostic Log and Trace Modulinstanz als Empfänger.\n</li><li><strong>Schnittstelle / API</strong>: Synchrone C-Funktion <code>Dlt_Init(const Dlt_ConfigType*)</code>.\n</li><li><strong>Kommentar-Notiz</strong>: <code>Comment: Initialization of DLT is performed synchronously</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>EcuM</code> initiiert über einen synchronen Aufruf <code>Dlt_Init(const Dlt_ConfigType*)</code> die Initialisierung des Moduls <code>Dlt</code>.\n</li><li>Während der Abarbeitung von <code>Dlt_Init</code> ist die Ausführungsleiste (Activation Bar) auf der Lebenslinie von <code>Dlt</code> aktiv.\n</li><li>Nach Abschluss der Initialisierung erfolgt der synchrone Rücksprung (gestrichelter Pfeil) an den aufrufenden <code>EcuM</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Aufruf von <code>Dlt_Init</code> mit einem Zeiger auf die modulspezifische Konfigurationsstruktur (<code>const Dlt_ConfigType*</code>) ist normativ synchron auszuführen. Entwickler müssen sicherstellen, dass <code>Dlt_Init</code> im Startphasen-Ablauf des ECU State Managers aufgerufen wird und die Konfigurationsdaten vor dem Aufruf gültig bereitstehen. Rückgabewerte sind im Sequenzdiagramm nicht definiert (Rücksprung erfolgt <code>void</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f85fc1d20bf2cf98", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Initialisierung des Basissoftware-Moduls Diagnostic Log and Trace (DLT) innerhalb der AUTOSAR Classic Platform-Architektur. Dargestellt ist die synchrone Interaktion zwischen dem ECU State Manager (<code>EcuM</code>) als Aufrufer und dem DLT-Modul (<code>Dlt</code>) während der BSW-Startphase.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>EcuM</strong> (<code>«module» EcuM</code>): ECU State Manager als BSW-Komponente, agiert als Initiator des Initialisierungsaufrufs.\n</li><li><strong>Dlt</strong> (<code>«module» Dlt :Dlt</code>): Diagnostic Log and Trace Modulinstanz als Empfänger.\n</li><li><strong>Schnittstelle / API</strong>: Synchrone C-Funktion <code>Dlt_Init(const Dlt_ConfigType*)</code>.\n</li><li><strong>Kommentar-Notiz</strong>: <code>Comment: Initialization of DLT is performed synchronously</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>EcuM</code> initiiert über einen synchronen Aufruf <code>Dlt_Init(const Dlt_ConfigType*)</code> die Initialisierung des Moduls <code>Dlt</code>.\n</li><li>Während der Abarbeitung von <code>Dlt_Init</code> ist die Ausführungsleiste (Activation Bar) auf der Lebenslinie von <code>Dlt</code> aktiv.\n</li><li>Nach Abschluss der Initialisierung erfolgt der synchrone Rücksprung (gestrichelter Pfeil) an den aufrufenden <code>EcuM</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Aufruf von <code>Dlt_Init</code> mit einem Zeiger auf die modulspezifische Konfigurationsstruktur (<code>const Dlt_ConfigType*</code>) ist normativ synchron auszuführen. Entwickler müssen sicherstellen, dass <code>Dlt_Init</code> im Startphasen-Ablauf des ECU State Managers aufgerufen wird und die Konfigurationsdaten vor dem Aufruf gültig bereitstehen. Rückgabewerte sind im Sequenzdiagramm nicht definiert (Rücksprung erfolgt <code>void</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4d9e1b89b5e2113c", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Initialisierung des Basissoftware-Moduls Diagnostic Log and Trace (DLT) innerhalb der AUTOSAR Classic Platform-Architektur. Dargestellt ist die synchrone Interaktion zwischen dem ECU State Manager (<code>EcuM</code>) als Aufrufer und dem DLT-Modul (<code>Dlt</code>) während der BSW-Startphase.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>EcuM</strong> (<code>«module» EcuM</code>): ECU State Manager als BSW-Komponente, agiert als Initiator des Initialisierungsaufrufs.\n</li><li><strong>Dlt</strong> (<code>«module» Dlt :Dlt</code>): Diagnostic Log and Trace Modulinstanz als Empfänger.\n</li><li><strong>Schnittstelle / API</strong>: Synchrone C-Funktion <code>Dlt_Init(const Dlt_ConfigType*)</code>.\n</li><li><strong>Kommentar-Notiz</strong>: <code>Comment: Initialization of DLT is performed synchronously</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>EcuM</code> initiiert über einen synchronen Aufruf <code>Dlt_Init(const Dlt_ConfigType*)</code> die Initialisierung des Moduls <code>Dlt</code>.\n</li><li>Während der Abarbeitung von <code>Dlt_Init</code> ist die Ausführungsleiste (Activation Bar) auf der Lebenslinie von <code>Dlt</code> aktiv.\n</li><li>Nach Abschluss der Initialisierung erfolgt der synchrone Rücksprung (gestrichelter Pfeil) an den aufrufenden <code>EcuM</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Aufruf von <code>Dlt_Init</code> mit einem Zeiger auf die modulspezifische Konfigurationsstruktur (<code>const Dlt_ConfigType*</code>) ist normativ synchron auszuführen. Entwickler müssen sicherstellen, dass <code>Dlt_Init</code> im Startphasen-Ablauf des ECU State Managers aufgerufen wird und die Konfigurationsdaten vor dem Aufruf gültig bereitstehen. Rückgabewerte sind im Sequenzdiagramm nicht definiert (Rücksprung erfolgt <code>void</code>).</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-cb53132001ee1c4c", "to": "FIG-f85fc1d20bf2cf98", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f85fc1d20bf2cf98", "to": "FIG-4d9e1b89b5e2113c", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
